page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state n = 0
  ref stat
  ref io
  ref raf

  computed shown = `${n.toLocaleString("es-AR")}+`

  fn start() {
    let t0 = performance.now()
    let dur = 2000
    let tick = now => {
      let p = Math.min((now - t0) / dur, 1)
      n = Math.round(12000 * (1 - Math.pow(1 - p, 3)))
      if (p < 1) { raf = requestAnimationFrame(tick) }
    }
    raf = requestAnimationFrame(tick)
  }

  fn onSeen(reduce) {
    if reduce {
      n = 12000
    } else {
      start()
    }
  }

  mount {
    let reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    io = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting) {
        io.disconnect()
        onSeen(reduce)
      }
    }, { threshold: 0.5 })
    io.observe(stat)
    cleanup {
      io.disconnect()
      cancelAnimationFrame(raf)
    }
  }

