            {card.icon}
          </div>
          <h3 className="mb-2 text-xl font-semibold text-white">{card.title}</h3>
          <p className="text-slate-300">{card.text}</p>
        </article>
      ))}
    </div>
  );
}

const TARGET = 12000;
