import { createEffect, createSignal, onCleanup, untrack } from "solid-js";
import { useInView, usePrefersReducedMotion } from "./motion";

const TARGET = 12000;
const DURATION = 2000;

const format = (n: number) =>
  Math.round(n)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, ".");

export default function Counter() {
  const reduced = usePrefersReducedMotion();
  const [inView, ref] = useInView(0.4);
  const [value, setValue] = createSignal(0);
  let started = false;

  createEffect(() => {
    if (!inView() || started) return;
    started = true;

    if (untrack(reduced)) {
      setValue(TARGET);
      return;
    }

    const start = performance.now();
    let raf = 0;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / DURATION);
      const eased = 1 - Math.pow(1 - t, 3);
      setValue(TARGET * eased);
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    onCleanup(() => cancelAnimationFrame(raf));
  });

  return (
    <section class="bg-slate-900 px-6 py-24 text-center">
      <div ref={ref}>
        <p class="text-6xl font-extrabold tabular-nums text-white sm:text-7xl" aria-hidden="true">
          {format(value())}+
        </p>
        <span class="sr-only">12.000+ usuarios</span>
        <p class="mt-3 text-lg text-slate-300" aria-hidden="true">
          usuarios confían en Nimbus
        </p>
