import { createEffect, createMemo, createSignal, onCleanup, type Component } from "solid-js";
import { createInView, createReducedMotion } from "./motion";

const TARGET = 12000;
const DURATION_MS = 2000;
const formatter = new Intl.NumberFormat("es-AR");

const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

const Counter: Component = () => {
  let ref: HTMLElement | undefined;
  const reduced = createReducedMotion();
  const inView = createInView(() => ref, { threshold: 0.5 });
  const [value, setValue] = createSignal(0);

  let frame = 0;
  let started = false;
  let done = false;

  createEffect(() => {
    const isVisible = inView();
    const isReduced = reduced();

    if (done || !isVisible) return;

    if (isReduced) {
      cancelAnimationFrame(frame);
      setValue(TARGET);
      done = true;
      return;
    }

    if (started) return;
    started = true;

    const start = performance.now();
    const step = (now: number) => {
      const t = Math.min((now - start) / DURATION_MS, 1);
      setValue(Math.round(TARGET * easeOutCubic(t)));
      if (t < 1) {
        frame = requestAnimationFrame(step);
      } else {
        done = true;
      }
    };
    frame = requestAnimationFrame(step);
  });

  onCleanup(() => cancelAnimationFrame(frame));

  const formatted = createMemo(() => formatter.format(value()));

  return (
    <section ref={ref} class="px-6 pb-28 pt-8 text-center">
      <p class="sr-only">Más de {formatter.format(TARGET)} usuarios</p>
      <div aria-hidden="true">
        <span class="bg-gradient-to-r from-indigo-400 via-fuchsia-400 to-pink-400 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-8xl">
          {formatted()}+
        </span>
        <p class="mt-3 text-lg uppercase tracking-widest text-slate-400">usuarios</p>
      </div>
    </section>
  );
};

export default Counter;

